          if (y >= hgt - 5 && hgt === last) break; last = hgt;
        }
        await p.waitForTimeout(1500);
        const info = await p.evaluate(() => ({
          h: document.body.scrollHeight,
          sections: [...document.querySelectorAll('section, [id]')].filter(e=>e.tagName==='SECTION'||e.id).length,
          words: document.body.innerText.split(/\s+/).length,
          ctas: [...document.querySelectorAll('a,button')].filter(e=>e.offsetParent).length,
