        }));
        console.log(name, vw, JSON.stringify(info));
        await p.evaluate(() => window.scrollTo(0,0));
        await p.screenshot({ path: `shots/${name}-${vw}.png`, fullPage: true });
      } catch (e) { console.log(name, vw, 'ERR', e.message); }
      await p.close();
    }
  }
  await b.close();
})();
