    await p.waitForTimeout(300);
    const sel = p.locator('main select');
    for (let i = 0; i < await sel.count(); i++) { const opts = await sel.nth(i).locator('option').allTextContents(); if (opts[1]) await sel.nth(i).selectOption({ index: 1 }); }
    const next = p.getByRole('button', { name: /next|continue|see|report|results|generate/i }).last();
    const dis = await next.isDisabled().catch(()=>true);
    if (dis) { console.log('next disabled at', s, await p.evaluate(()=>[...document.querySelectorAll('main button')].map(b=>b.innerText.trim().slice(0,30)).join(' | '))); break; }
    await next.click(); await p.waitForTimeout(1200);
  }
  await p.waitForTimeout(1500);
  await p.screenshot({ path: `shots/pp-${vw}-report.png`, fullPage: true });
  const r = await p.evaluate(() => ({ h: document.body.scrollHeight, words: document.querySelector('main').innerText.split(/\s+/).length,
    clicks: [...document.querySelectorAll('main a, main button')].filter(e=>e.offsetParent).map(e=>(e.innerText||e.getAttribute('aria-label')||'').replace(/\s+/g,' ').trim().slice(0,50)),
    heads: [...document.querySelectorAll('main h2, main h3')].map(e=>e.innerText.replace(/\s+/g,' ').slice(0,80)) }));
  console.log(vw, 'report', JSON.stringify(r));
  await ctx.close();
  }
  await b.close();
})();
EOF
